create table if not exists products (
  id bigint generated by default as identity primary key,
  num text default '',
  category text not null,
  type text not null check (type in ('pizza','single')),
  pizza_type text check (pizza_type in ('salgada','doce')),
  is_custom boolean default false,
  name text not null,
  description text default '',
  price numeric,
  price_25 numeric,
  price_35 numeric,
  price_30x50 numeric,
  available boolean default true,
  sort_order integer default 0,
  created_at timestamptz default now()
);

alter table products enable row level security;

create policy "public can read available products"
on products for select
using (available = true);

-- DEMONSTRAÇÃO: permite a dashboard alterar os produtos.
-- Não é seguro para produção porque o login pizza/123 é apenas visual.
create policy "demo can insert products" on products for insert with check (true);
create policy "demo can update products" on products for update using (true) with check (true);
create policy "demo can delete products" on products for delete using (true);

on conflict (id) do update set
name=excluded.name, description=excluded.description, category=excluded.category,
type=excluded.type, pizza_type=excluded.pizza_type, is_custom=excluded.is_custom,
price=excluded.price, price_25=excluded.price_25, price_35=excluded.price_35,
price_30x50=excluded.price_30x50, available=excluded.available, sort_order=excluded.sort_order;
